[
  {
    "role": "paragraph",
    "segment": "Here is a C-like, array-based stack with a fixed capacity of 100 for integers. It provides empty, full, push, pop, and top operations as described:

#define MAX_STACK 100

typedef struct {
    int data[MAX_STACK];
    int size;
} Stack;

void initStack(Stack* s) { s->size = 0; }

int isEmpty(const Stack* s) { return s->size == 0; }

int isFull(const Stack* s) { return s->size == MAX_STACK; }

int push(Stack* s, int value) {
    if (isFull(s)) return -1; // error: stack is full
    s->data[s->size++] = value;
    return 0;
}

int pop(Stack* s, int* out) {
    if (isEmpty(s)) return -1; // error: stack is empty
    *out = s->data[--s->size];
    return 0;
}

int topElem(const Stack* s, int* out) {
    if (isEmpty(s)) return -1; // error: empty
    *out = s->data[s->size - 1];
    return 0;
}",
    "citations": [],
    "type": null
  }
]

answer:
Here is a C-like, array-based stack with a fixed capacity of 100 for integers. It provides empty, full, push, pop, and top operations as described:

#define MAX_STACK 100

typedef struct {
    int data[MAX_STACK];
    int size;
} Stack;

void initStack(Stack* s) { s->size = 0; }

int isEmpty(const Stack* s) { return s->size == 0; }

int isFull(const Stack* s) { return s->size == MAX_STACK; }

int push(Stack* s, int value) {
    if (isFull(s)) return -1; // error: stack is full
    s->data[s->size++] = value;
    return 0;
}

int pop(Stack* s, int* out) {
    if (isEmpty(s)) return -1; // error: stack is empty
    *out = s->data[--s->size];
    return 0;
}

int topElem(const Stack* s, int* out) {
    if (isEmpty(s)) return -1; // error: empty
    *out = s->data[s->size - 1];
    return 0;
}

